export type UserMessageType = "button_click";

export type EventMetadata = {
  user_message_type?: UserMessageType;
  button_title?: string;
  active_flow?: string;
  utter_action?: string;
  flow_id?: string;
  langfuse_trace_id?: string;
  langfuse_trace_url?: string;
  langfuse_session_url?: string;
  execution_success?: boolean;
  execution_error_message?: string;
  execution_times?: RasaExecutionTime;
  voice_latency?: VoiceLatency;
  barge_in_verdict?: BargeInVerdict;
  reason?: string;
  playback?: BargeInPlayback;
  latency_breakdown?: LatencyBreakdown;
  step_id?: string;
  /**
   * `originalTimestamp` of the user message that triggered a skill activation
   * (stamped by the engine). The text is resolved on the frontend by matching
   * this against the conversation's user utterances.
   */
  triggering_user_message_timestamp?: number;
  rawEvent?: RawEvent;
  reset?: boolean;
  was_modified_by_studio?: boolean;
  domain_ground_truth?: string;
  metadata?: {
    rephrase?: boolean;
    rephrasePrompt?: string;
  };
  tool_name?: string;
  /** Id of the LLM tool call this marker records (METADATA_TOOL_CALL_ID). */
  tool_call_id?: string | null;
  tool_arguments?: Record<string, unknown>;
  tool_result?: unknown;
  tool_is_error?: boolean;
  tool_error_message?: string;
  tool_source?: ToolSource;
  tool_mcp_server?: string;
  mcp_server?: string;
  /** Owning skill of a skill-scoped event (e.g. a tool dispatch), when stamped. */
  skill_id?: string;
  timeout?: number;
  /** Payload of a frontend-synthesized LLM-call event (skill engine). */
  llm_call?: LlmCallRecord;
  /** Skill-engine response provenance: verbatim template, rephrased template, LLM text, filler. */
  mantle_response_source?: "verbatim" | "rephrased" | "llm" | "filler";
  /** Skill-engine write provenance stamped on tool-produced memory writes. */
  mantle_write_provenance?: {
    tool?: string | null;
    /** Owning skill of the write's active scope, or null while routing. */
    skill_id?: string | null;
    step?: string | null;
    frame_id?: string | null;
    arguments?: Record<string, unknown>;
    position?: number;
    /** Id of the dispatching LLM tool call, stamped when available. */
    tool_call_id?: string | null;
  };
  parseData: unknown;
  description?: string;
  mcp_tools?: string[];
  excluded_mcp_tools?: string[];
  exit_conditions?: string[];
  interrupted_flow_ids?: string[];
  streaming?: boolean;
  session_id?: string;
};

// Local mirror of `@rasahq/rasa-events`' JsonValue so the published types
// don't depend on that package (it is bundled, not a runtime dependency).
type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };

export type RawEvent = {
  name: string;
  key?: string;
  metadata: EventMetadata;
  timestamp: number;
  /** ProtoJSON envelope identity; absent on classic flat events. */
  event_id?: string;
  sequence?: number;
  /**
   * The ProtoJSON envelope this flat event was normalized from. Replay sends
   * it back verbatim so the backend re-reads the exact wire payload.
   */
  protoJsonSource?: JsonValue;
  tool_name?: string;
  /** Subject skill, or owning skill of a v2 flow lifecycle event. */
  skill_id?: string;
  block_id?: string;
  agent_id?: string;
  modality?: string;
  reason?: string;
  timeout?: number;
  arguments?: Record<string, unknown>;
  result?: unknown;
  is_error?: boolean;
  error_message?: string;
  source?: ToolSource;
  mcp_server?: string;
  event:
    | "user"
    | "stack"
    | "action"
    | "bot"
    | "slot"
    | "memory_set"
    | "memory_cleared"
    | "agent"
    | "agent_started"
    | "agent_completed"
    | "agent_interrupted"
    | "agent_cancelled"
    | "agent_resumed"
    | "flow_started"
    | "flow_completed"
    | "flow_cancelled"
    | "flow_interrupted"
    | "flow_resumed"
    | "skill_activated"
    | "skill_completed"
    | "skill_cancelled"
    | "skill_interrupted"
    | "skill_resumed"
    | "ordered_block_entered"
    | "ordered_block_completed"
    | "ordered_block_cancelled"
    | "ordered_block_interrupted"
    | "ordered_block_resumed"
    | "mcp_tool_executed"
    | "tool_executed"
    | "bot_turn_ended"
    | "tts_finished"
    | "user_barge_in"
    | "user_silence_timeout"
    | "user_input_suppressed"
    | "session_started"
    | "session_ended"
    | "inactive"
    | "unsupported_request_classified";
  conversation_id: string;
  text: string;
  data: BackendResponseData;
  update: string;
  flow_id: string;
  step_id: string;
  value?: unknown;
  parse_data: {
    intent_ranking: MessageIntent[];
    commands?: string;
  };
};

