export type TrackerResponseData = {
  sender_id: string;
  events: RawEvent[];
  slots: Record<string, SlotState>;
  stack: RawStack[];
  skill_state?: SkillState;
};

const RawStackSchema = z
  .object({
    frame_id: z.string(),
    flow_id: z.string().optional(),
    step_id: z.string().optional(),
    type: z.string().optional(),
    frame_type: z.string().optional(),
    skill_id: z.string().optional(),
    block_id: z.string().optional(),
    collect: z.string().optional(),
    utter: z.string().optional(),
  })
  .superRefine((frame, ctx) => {
    // Per-type identity: incomplete frames must fail parse so the tracker
    // hook keeps the prior stack instead of overwriting it.
    if (frame.type === "skill") {
      if (!frame.skill_id) {
        ctx.addIssue({
          code: "custom",
          path: ["skill_id"],
          message: "skill frame requires skill_id",
        });
      }
      return;
    }
    if (frame.type === "ordered_block") {
      if (!frame.skill_id) {
        ctx.addIssue({
          code: "custom",
          path: ["skill_id"],
          message: "ordered_block frame requires skill_id",
        });
      }
      if (!frame.block_id) {
        ctx.addIssue({
          code: "custom",
          path: ["block_id"],
          message: "ordered_block frame requires block_id",
        });
      }
      if (!frame.step_id) {
        ctx.addIssue({
          code: "custom",
          path: ["step_id"],
          message: "ordered_block frame requires step_id",
        });
      }
      return;
    }
    if (!frame.flow_id) {
      ctx.addIssue({
        code: "custom",
        path: ["flow_id"],
        message: "flow-like frame requires flow_id",
      });
    }
    if (!frame.step_id) {
      ctx.addIssue({
        code: "custom",
        path: ["step_id"],
        message: "flow-like frame requires step_id",
      });
    }
  });

const RawEventSchema = z.looseObject({
  event: z.string(),
  timestamp: z.number(),
});

export const TrackerResponseDataSchema = z.object({
  sender_id: z.string(),
  events: z.array(RawEventSchema).transform((events) => events as unknown as RawEvent[]),
  slots: z.record(z.string(), z.unknown()),
  stack: z.array(RawStackSchema),
  // Skill-engine payload; `catch` keeps a malformed skill_state from
  // discarding the whole tracker update.
  skill_state: SkillStateSchema.optional().catch(undefined),
});

